window.docContents[112].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Reduction":{"contents":"Likewise the definitions of IsValue and Step.\n\ninductive Tm.IsValue : Tm → Prop where\n  | abs : ∀ x τ₂ t₁,\n      IsValue <{λ ~x : ~τ₂ . ~t₁}>\n  | tru :\n      IsValue <{true}>\n  | fls :\n      IsValue <{false}>\n  | unit :\n      IsValue .unit\n\n-- Fill in more rules when you do the `products` exercise later\n--  FILL IN HERE\n\nattribute [StlcSubEval] Tm.IsValue.abs Tm.IsValue.tru Tm.IsValue.fls Tm.IsValue.unit\n\n\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Step t t'\n\ninductive Step : Tm → Tm → Prop where\n  -- pure STLC\n  | appAbs (x : String) (τ₂ : Ty) (t₁ v₂ : Tm) :\n        v₂.IsValue →\n         <{(λ ~x: ~τ₂ . ~t₁) ~v₂}> ⟶ <{ [~x := ~v₂] ~t₁ }>\n  | app₁ (t₁ t₁' t₂ : Tm) :\n         t₁ ⟶ t₁' →\n         <{~t₁ ~t₂}> ⟶ <{~t₁' ~t₂}>\n  | app₂ (v₁ t₂ t₂' : Tm) :\n        v₁.IsValue →\n         t₂ ⟶ t₂' →\n         <{~v₁ ~t₂}> ⟶ <{~v₁  ~t₂'}>\n  -- booleans\n  | ifStep (t₁ t₁' t₂ t₃ : Tm) (h : t₁ ⟶ t₁') :\n      <{ if ~t₁ then ~t₂ else ~t₃ }> ⟶ <{ if ~t₁' then ~t₂ else ~t₃ }>\n  | ifTrue (t₂ t₃ : Tm) :\n      <{ if true then ~t₂ else ~t₃ }> ⟶ t₂\n  | ifFalse (t₂ t₃ : Tm) :\n      <{ if false then ~t₂ else ~t₃ }> ⟶ t₃\n\n  -- Fill in more rules when you do the `products` exercise later\n  --  FILL IN HERE\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Step t t'\nscoped notation:40 t:41 \" ⟶* \" t':41 => Multi Step t t'\n\n-- Be sure to add your constructors for pairs to this list later\nattribute [StlcSubEval] Step.appAbs Step.app₁ Step.app₂\n    Step.ifStep Step.ifTrue Step.ifFalse\n--  FILL IN HERE\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Formal Definitions","header":"8.2.3. Reduction","id":"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Reduction"}});